import type { ContentPack } from '../types';
import { glesson as G, lesson, M, mix, Nq, TF } from '../lib';
import { electricPower, gears, ohm, seriesParallel } from '../gensSci';
import { loops, scale, spreadsheet } from '../gens';
import TD1 from './1E-TD';

const P: ContentPack = {
  '3E-TD-1': TD1['1E-TD-1'],
  '3E-TD-2': lesson(['El diseño de un prototipo es iterativo: se define el problema y los requisitos, se generan varias ideas, se elige la mejor con criterios (coste, seguridad, facilidad de construcción, impacto ambiental), se construye, se prueba y se mejora. En el diseño se tiene en cuenta la accesibilidad: que lo pueda usar cualquier persona.|El disseny d’un prototip és iteratiu: es definix el problema i els requisits, es generen diverses idees, es tria la millor amb criteris (cost, seguretat, facilitat de construcció, impacte ambiental), es construïx, es prova i es millora. En el disseny es té en compte l’accessibilitat: que el puga usar qualsevol persona.|Prototype design is iterative: define the problem and requirements, generate several ideas, choose the best using criteria (cost, safety, ease of building, environmental impact), build, test and improve. Design should be accessible so anyone can use it.'],
    'Diseñamos un dispensador de gel para el aula. ¿Qué requisito es de accesibilidad?|Dissenyem un dispensador de gel per a l’aula. Quin requisit és d’accessibilitat?|We are designing a hand-gel dispenser for class. Which requirement is about accessibility?', ['Que se pueda usar sin tocarlo con la mano.|Que es puga usar sense tocar-lo amb la mà.|It can be used without touching it.', 'Y a una altura que alcance cualquier persona, también en silla de ruedas.|I a una altura que abaste qualsevol persona, també en cadira de rodes.|And at a height anyone can reach, including wheelchair users.'], [
      M('Una matriz de decisión sirve para…|Una matriu de decisió servix per a…|A decision matrix helps you…', 'comparar ideas según criterios|comparar idees segons criteris|compare ideas against criteria', ['dibujar planos|dibuixar plànols|draw plans', 'calcular el IVA|calcular l’IVA|work out VAT'], 'Se puntúa cada idea.|Es puntua cada idea.|Each idea is scored.'),
      TF('Diseñar es un proceso de prueba y mejora continua.|Dissenyar és un procés de prova i millora contínua.|Design is a process of continual testing and improvement.', true, 'Iterar.|Iterar.|Iterate.'),
      M('Los requisitos de un diseño son…|Els requisits d’un disseny són…|Design requirements are…', 'las condiciones que debe cumplir la solución|les condicions que ha de complir la solució|the conditions the solution must meet', ['los colores favoritos|els colors preferits|favourite colours', 'las herramientas del taller|les eines del taller|the workshop tools'], 'Medidas, coste, seguridad…|Mesures, cost, seguretat…|Size, cost, safety…'),
      M('Una lluvia de ideas busca…|Una pluja d’idees busca…|Brainstorming aims to…', 'muchas ideas sin juzgarlas al principio|moltes idees sense jutjar-les al principi|produce lots of ideas without judging them at first', ['una sola idea perfecta|una sola idea perfecta|one perfect idea', 'copiar un producto|copiar un producte|copy a product'], 'Después se filtran.|Després es filtren.|Filter them later.'),
      TF('El impacto ambiental es un buen criterio para elegir materiales.|L’impacte ambiental és un bon criteri per a triar materials.|Environmental impact is a good criterion for choosing materials.', true, 'Reciclables, locales, duraderos.|Reciclables, locals, duradors.|Recyclable, local, durable.'),
      M('Probar el prototipo con usuarios reales sirve para…|Provar el prototip amb usuaris reals servix per a…|Testing the prototype with real users helps…', 'descubrir problemas que el diseñador no vio|descobrir problemes que el dissenyador no va veure|find problems the designer missed', ['perder tiempo|perdre temps|waste time', 'subir el precio|pujar el preu|raise the price'], 'Diseño centrado en las personas.|Disseny centrat en les persones.|People-centred design.'),
    ]),
  '3E-TD-3': lesson(['La fabricación digital crea objetos a partir de un archivo de ordenador. Impresión 3D (añade material capa a capa, normalmente PLA), corte láser (corta o graba madera, cartón, metacrilato) y fresadora CNC (quita material). Proceso: diseño CAD → archivo (STL, SVG) → preparar (laminador) → fabricar.|La fabricació digital crea objectes a partir d’un fitxer d’ordinador. Impressió 3D (afig material capa a capa, normalment PLA), tall làser (talla o grava fusta, cartó, metacrilat) i fresadora CNC (lleva material). Procés: disseny CAD → fitxer (STL, SVG) → preparar (laminador) → fabricar.|Digital fabrication makes objects from a computer file. 3D printing (adds material layer by layer, usually PLA), laser cutting (cuts or engraves wood, card, acrylic) and CNC milling (removes material). Process: CAD design → file (STL, SVG) → prepare (slicer) → make.'],
    '¿Qué diferencia hay entre impresión 3D y fresadora CNC?|Quina diferència hi ha entre impressió 3D i fresadora CNC?|What is the difference between 3D printing and CNC milling?', ['La impresora añade material.|La impressora afig material.|The printer adds material.', 'La fresadora lo quita: fabricación sustractiva.|La fresadora el lleva: fabricació sostractiva.|The mill removes it: subtractive manufacturing.'], [
      M('El formato de archivo típico para impresión 3D es…|El format de fitxer típic per a impressió 3D és…|The usual file format for 3D printing is…', 'STL|STL|STL', ['MP3|MP3|MP3', 'DOCX|DOCX|DOCX'], 'Describe la superficie con triángulos.|Descriu la superfície amb triangles.|It describes the surface with triangles.'),
      M('El PLA, plástico usado en impresión 3D, se obtiene de…|El PLA, plàstic usat en impressió 3D, s’obté de…|PLA, used in 3D printing, is made from…', 'almidón de maíz u otras plantas|midó de dacsa o altres plantes|corn starch or other plants', ['petróleo únicamente|petroli únicament|crude oil only', 'metal|metall|metal'], 'Bioplástico.|Bioplàstic.|A bioplastic.'),
      TF('Con un láser se puede grabar un dibujo sobre madera.|Amb un làser es pot gravar un dibuix sobre fusta.|A laser can engrave a picture onto wood.', true, 'Quema la superficie con precisión.|Crema la superfície amb precisió.|It burns the surface precisely.'),
      M('El programa que divide el modelo 3D en capas es el…|El programa que dividix el model 3D en capes és el…|The program that slices a 3D model into layers is the…', 'laminador (slicer)|laminador (slicer)|slicer', ['navegador|navegador|browser', 'antivirus|antivirus|antivirus'], 'Genera las instrucciones para la impresora.|Genera les instruccions per a la impressora.|It creates the printer instructions.'),
      M('Una ventaja de la fabricación digital es…|Un avantatge de la fabricació digital és…|An advantage of digital fabrication is…', 'fabricar piezas personalizadas con precisión|fabricar peces personalitzades amb precisió|making precise custom parts', ['que no necesita diseño|que no necessita disseny|needing no design', 'que no consume energía|que no consumix energia|using no energy'], 'Del diseño al objeto.|Del disseny a l’objecte.|From design to object.'),
      TF('Las impresoras 3D se pueden dejar funcionando sin ninguna supervisión en el aula.|Les impressores 3D es poden deixar funcionant sense cap supervisió en l’aula.|3D printers can be left running unsupervised in class.', false, 'Alcanzan altas temperaturas.|Arriben a altes temperatures.|They reach high temperatures.'),
    ]),
  '3E-TD-4': G(['La escala relaciona el dibujo con la realidad: 1:100 (reducción), 1:1 (natural), 5:1 (ampliación). Acotar es poner medidas en un plano con líneas de cota y cifras en milímetros. El dibujo asistido por ordenador (CAD: FreeCAD, Tinkercad, LibreCAD) permite planos precisos y modelos 3D.|L’escala relaciona el dibuix amb la realitat: 1:100 (reducció), 1:1 (natural), 5:1 (ampliació). Acotar és posar mesures en un plànol amb línies de cota i xifres en mil·límetres. El dibuix assistit per ordinador (CAD: FreeCAD, Tinkercad, LibreCAD) permet plànols precisos i models 3D.|Scale relates the drawing to reality: 1:100 (reduction), 1:1 (full size), 5:1 (enlargement). Dimensioning adds measurements to a drawing with dimension lines and figures in millimetres. Computer-aided design (CAD: FreeCAD, Tinkercad, LibreCAD) gives precise drawings and 3D models.'],
    'Una habitación de 4 m en un plano 1:50. ¿Cuánto mide en el plano?|Una habitació de 4 m en un plànol 1:50. Quant mesura en el plànol?|A 4 m room on a 1:50 plan. How long is it on the plan?', ['4 m = 400 cm.|4 m = 400 cm.|4 m = 400 cm.', '400 / 50 = 8 cm.|400 / 50 = 8 cm.|400 ÷ 50 = 8 cm.'], scale(), [
      M('En dibujo técnico las cotas se expresan normalmente en…|En dibuix tècnic les cotes s’expressen normalment en…|In technical drawing, dimensions are usually given in…', 'milímetros|mil·límetres|millimetres', ['metros|metres|metres', 'pulgadas|polzades|inches'], 'Sin escribir la unidad.|Sense escriure la unitat.|Without writing the unit.'),
      M('Tinkercad y FreeCAD son programas de…|Tinkercad i FreeCAD són programes de…|Tinkercad and FreeCAD are…', 'diseño asistido por ordenador (CAD)|disseny assistit per ordinador (CAD)|computer-aided design (CAD) programs', ['edición de vídeo|edició de vídeo|video editors', 'hojas de cálculo|fulls de càlcul|spreadsheets'], 'Para planos y modelos 3D.|Per a plànols i models 3D.|For drawings and 3D models.'),
      TF('Una escala 1:1 representa el objeto a tamaño real.|Una escala 1:1 representa l’objecte a mida real.|A 1:1 scale shows the object at real size.', true, 'Escala natural.|Escala natural.|Full size.'),
    ]),
  '3E-TD-5': TD1['1E-TD-5'],
  '3E-TD-6': lesson(['Los plásticos son materiales sintéticos (casi todos del petróleo). Tipos: termoplásticos (se ablandan con calor y se pueden reciclar: PET, PVC, polietileno, PLA), termoestables (no se ablandan: baquelita, resinas) y elastómeros (elásticos: caucho, neopreno). Ventajas: ligeros, aislantes, baratos. Problema: residuos y microplásticos.|Els plàstics són materials sintètics (quasi tots del petroli). Tipus: termoplàstics (s’estovien amb calor i es poden reciclar: PET, PVC, polietilé, PLA), termoestables (no s’estovien: baquelita, resines) i elastòmers (elàstics: cautxú, neopré). Avantatges: lleugers, aïllants, barats. Problema: residus i microplàstics.|Plastics are synthetic materials (mostly from oil). Types: thermoplastics (soften with heat and can be recycled: PET, PVC, polyethylene, PLA), thermosets (do not soften: Bakelite, resins) and elastomers (elastic: rubber, neoprene). Advantages: light, insulating, cheap. Problem: waste and microplastics.'],
    'Una botella de agua (PET) se puede fundir y volver a moldear. ¿Qué tipo de plástico es?|Una botella d’aigua (PET) es pot fondre i tornar a modelar. Quin tipus de plàstic és?|A water bottle (PET) can be melted and remoulded. What type of plastic is it?', ['Se ablanda con el calor.|S’estovia amb la calor.|It softens with heat.', 'Termoplástico.|Termoplàstic.|A thermoplastic.'], [
      M('Los enchufes antiguos de baquelita son de plástico…|Els endolls antics de baquelita són de plàstic…|Old Bakelite plugs are made of…', 'termoestable|termoestable|a thermoset', ['termoplástico|termoplàstic|a thermoplastic', 'elastómero|elastòmer|an elastomer'], 'No se ablanda con calor.|No s’estovia amb calor.|It does not soften with heat.'),
      M('Un neumático es de…|Un pneumàtic és de…|A tyre is made of…', 'elastómero (caucho)|elastòmer (cautxú)|an elastomer (rubber)', ['termoestable|termoestable|a thermoset', 'madera|fusta|wood'], 'Elástico.|Elàstic.|Elastic.'),
      TF('Los plásticos son buenos aislantes eléctricos.|Els plàstics són bons aïllants elèctrics.|Plastics are good electrical insulators.', true, 'Por eso recubren los cables.|Per això recobrixen els cables.|That is why they cover wires.'),
      M('Los microplásticos son…|Els microplàstics són…|Microplastics are…', 'trozos diminutos de plástico que contaminan|trossos diminuts de plàstic que contaminen|tiny pieces of plastic that pollute', ['plásticos muy resistentes|plàstics molt resistents|very strong plastics', 'plásticos comestibles|plàstics comestibles|edible plastics'], 'Llegan al mar y a los alimentos.|Arriben a la mar i als aliments.|They reach the sea and our food.'),
      M('El conformado por inyección consiste en…|El conformat per injecció consistix en…|Injection moulding means…', 'meter plástico fundido en un molde|ficar plàstic fos en un motle|forcing molten plastic into a mould', ['cortar con láser|tallar amb làser|laser cutting', 'tejer fibras|teixir fibres|weaving fibres'], 'Tapones, juguetes, carcasas.|Taps, joguets, carcasses.|Lids, toys, cases.'),
      TF('Todos los plásticos se reciclan igual de fácil.|Tots els plàstics es reciclen igual de fàcil.|All plastics are equally easy to recycle.', false, 'Los termoestables son muy difíciles de reciclar.|Els termoestables són molt difícils de reciclar.|Thermosets are very hard to recycle.'),
    ]),
  '3E-TD-7': lesson(['Las estructuras se apoyan de distintas formas: empotramiento (no se mueve ni gira), apoyo fijo (gira pero no se desplaza) y apoyo móvil (gira y se desliza). Las cargas pueden ser fijas (el propio peso) o variables (personas, viento, nieve). Cada elemento soporta esfuerzos: tracción, compresión, flexión, torsión y cortadura.|Les estructures es recolzen de diferents maneres: encastament (no es mou ni gira), suport fix (gira però no es desplaça) i suport mòbil (gira i llisca). Les càrregues poden ser fixes (el pes propi) o variables (persones, vent, neu). Cada element suporta esforços: tracció, compressió, flexió, torsió i cisallament.|Structures are supported in different ways: fixed (no movement or rotation), pinned (rotates but does not move) and roller (rotates and slides). Loads can be permanent (self-weight) or variable (people, wind, snow). Each part carries forces: tension, compression, bending, torsion and shear.'],
    '¿Por qué los puentes largos tienen apoyos móviles en un extremo?|Per què els ponts llargs tenen suports mòbils en un extrem?|Why do long bridges have a roller support at one end?', ['El material se dilata con el calor.|El material es dilata amb la calor.|The material expands with heat.', 'El apoyo móvil deja que se deslice sin romperse.|El suport mòbil deixa que llisque sense trencar-se.|The roller lets it slide without cracking.'], [
      M('Una viga horizontal cargada en el centro sufre sobre todo…|Una biga horitzontal carregada en el centre patix sobretot…|A horizontal beam loaded in the middle mainly experiences…', 'flexión|flexió|bending', ['torsión|torsió|torsion', 'tracción pura|tracció pura|pure tension'], 'La parte de arriba se comprime y la de abajo se estira.|La part de dalt es comprimix i la de baix s’estira.|The top compresses and the bottom stretches.'),
      M('Una farola clavada en el suelo es un apoyo de tipo…|Un fanal clavat a terra és un suport de tipus…|A lamp post set in the ground is a…', 'empotramiento|encastament|fixed support', ['móvil|mòbil|roller support', 'fijo articulado|fix articulat|pinned support'], 'No puede girar ni moverse.|No pot girar ni moure’s.|It cannot turn or move.'),
      M('El peso de la nieve sobre un tejado es una carga…|El pes de la neu sobre una teulada és una càrrega…|The weight of snow on a roof is a…', 'variable|variable|variable load', ['fija|fixa|permanent load', 'nula|nul·la|zero load'], 'No siempre está.|No sempre hi és.|It is not always there.'),
      TF('Los cables de un puente colgante trabajan a tracción.|Els cables d’un pont penjant treballen a tracció.|The cables of a suspension bridge are in tension.', true, 'Tiran del tablero.|Estiren del tauler.|They pull on the deck.'),
      M('Los arcos de piedra trabajan sobre todo a…|Els arcs de pedra treballen sobretot a…|Stone arches mainly work in…', 'compresión|compressió|compression', ['tracción|tracció|tension', 'torsión|torsió|torsion'], 'La piedra resiste bien la compresión.|La pedra resistix bé la compressió.|Stone resists compression well.'),
      M('Un tirante es un elemento que trabaja a…|Un tirant és un element que treballa a…|A tie is a member that works in…', 'tracción|tracció|tension', ['compresión|compressió|compression', 'flexión|flexió|bending'], 'Tira de dos puntos.|Estira de dos punts.|It pulls two points together.'),
    ]),
  '3E-TD-8': TD1['1E-TD-8'],
  '3E-TD-9': G(['Relación de transmisión: i = velocidad del conducido / velocidad del motor = z₁ / z₂ (o d₁ / d₂). Tren de engranajes: la relación total es el producto de las relaciones. Otros mecanismos: tornillo sinfín (gran reducción), piñón-cremallera (giro → recto), biela-manivela (giro → vaivén), leva (giro → subida y bajada).|Relació de transmissió: i = velocitat del conduït / velocitat del motor = z₁ / z₂ (o d₁ / d₂). Tren d’engranatges: la relació total és el producte de les relacions. Altres mecanismes: vis sens fi (gran reducció), pinyó-cremallera (gir → recte), biela-manovella (gir → vaivé), lleva (gir → pujada i baixada).|Gear ratio: i = driven speed ÷ driver speed = z₁ ÷ z₂ (or d₁ ÷ d₂). In a gear train, the total ratio is the product of the ratios. Other mechanisms: worm gear (big reduction), rack and pinion (rotary → linear), crank and slider (rotary → back-and-forth), cam (rotary → up and down).'],
    'Motor de 10 dientes a 1 200 rpm mueve uno de 40. ¿rpm del conducido?|Motor de 10 dents a 1 200 rpm mou un de 40. rpm del conduït?|A 10-tooth driver at 1,200 rpm turns a 40-tooth gear. Driven rpm?', ['i = 10 / 40 = 1/4.|i = 10 / 40 = 1/4.|i = 10 ÷ 40 = 1/4.', '1 200 / 4 = 300 rpm.|1 200 / 4 = 300 rpm.|1,200 ÷ 4 = 300 rpm.'], gears(), [
      M('¿Qué mecanismo transforma giro en movimiento rectilíneo?|Quin mecanisme transforma gir en moviment rectilini?|Which mechanism turns rotation into straight-line motion?', 'piñón-cremallera|pinyó-cremallera|rack and pinion', ['polea simple|politja simple|single pulley', 'palanca|palanca|lever'], 'Como en la dirección de un coche.|Com en la direcció d’un cotxe.|Like a car’s steering.'),
      M('El tornillo sinfín se usa cuando se necesita…|El vis sens fi s’usa quan es necessita…|A worm gear is used when you need…', 'una gran reducción de velocidad|una gran reducció de velocitat|a large speed reduction', ['aumentar mucho la velocidad|augmentar molt la velocitat|a big speed increase', 'cambiar el color|canviar el color|a colour change'], 'Cada vuelta avanza un diente.|Cada volta avança una dent.|Each turn moves one tooth.'),
    ]),
  '3E-TD-10': G(['Magnitudes eléctricas: voltaje o tensión (V, voltios), intensidad (I, amperios), resistencia (R, ohmios), potencia (P, vatios) y energía (E, kWh o julios). Ley de Ohm: V = I · R. Potencia: P = V · I. Se miden con el polímetro: voltímetro en paralelo y amperímetro en serie.|Magnituds elèctriques: voltatge o tensió (V, volts), intensitat (I, amperes), resistència (R, ohms), potència (P, watts) i energia (E, kWh o joules). Llei d’Ohm: V = I · R. Potència: P = V · I. Es mesuren amb el polímetre: voltímetre en paral·lel i amperímetre en sèrie.|Electrical quantities: voltage (V, volts), current (I, amps), resistance (R, ohms), power (P, watts) and energy (E, kWh or joules). Ohm’s law: V = I × R. Power: P = V × I. A multimeter measures them: voltmeter in parallel, ammeter in series.'],
    'Una bombilla de 12 V consume 0,5 A. ¿Potencia?|Una bombeta de 12 V consumix 0,5 A. Potència?|A 12 V bulb draws 0.5 A. Power?', ['P = V · I = 12 · 0,5.|P = V · I = 12 · 0,5.|P = V × I = 12 × 0.5.', '6 W.|6 W.|6 W.'], mix(ohm(), seriesParallel(), electricPower())),
  '3E-TD-11': lesson(['Para diseñar circuitos se usan símbolos normalizados: pila, interruptor, pulsador, conmutador, bombilla, motor, resistencia, LED. Montajes: serie (misma intensidad), paralelo (mismo voltaje), mixto. Con dos conmutadores se enciende una luz desde dos sitios (como en un pasillo). Se pueden simular antes en el ordenador (Tinkercad Circuits, Crocodile).|Per a dissenyar circuits s’usen símbols normalitzats: pila, interruptor, polsador, commutador, bombeta, motor, resistència, LED. Muntatges: sèrie (mateixa intensitat), paral·lel (mateix voltatge), mixt. Amb dos commutadors s’encén una llum des de dos llocs (com en un corredor). Es poden simular abans en l’ordinador (Tinkercad Circuits, Crocodile).|Circuit design uses standard symbols: cell, switch, push button, changeover switch, lamp, motor, resistor, LED. Arrangements: series (same current), parallel (same voltage), combined. Two two-way switches let you control one light from two places (like a hallway). You can simulate first on a computer (Tinkercad Circuits, Crocodile).'],
    '¿Cómo enciendes la luz del pasillo desde los dos extremos?|Com encens la llum del corredor des dels dos extrems?|How do you switch a hallway light from both ends?', ['Con un conmutador en cada extremo.|Amb un commutador en cada extrem.|Use a two-way switch at each end.', 'Cualquiera de los dos cambia el estado de la luz.|Qualsevol dels dos canvia l’estat de la llum.|Either one changes the light’s state.'], [
      M('Un pulsador se diferencia de un interruptor en que…|Un polsador es diferencia d’un interruptor en què…|A push button differs from a switch because…', 'solo funciona mientras lo mantienes pulsado|només funciona mentre el mantens premut|it only works while held down', ['es más grande|és més gran|it is bigger', 'no conduce|no conduïx|it does not conduct'], 'Como el timbre.|Com el timbre.|Like a doorbell.'),
      TF('En paralelo, todos los receptores reciben el mismo voltaje.|En paral·lel, tots els receptors reben el mateix voltatge.|In parallel, all components get the same voltage.', true, 'Por eso así se conecta una casa.|Per això així es connecta una casa.|That is how houses are wired.'),
      M('Un LED necesita una resistencia en serie para…|Un LED necessita una resistència en sèrie per a…|An LED needs a series resistor to…', 'limitar la corriente y no quemarse|limitar el corrent i no cremar-se|limit the current so it does not burn out', ['brillar de otro color|brillar d’un altre color|glow a different colour', 'funcionar sin pila|funcionar sense pila|work without a battery'], 'Protección.|Protecció.|Protection.'),
      M('En serie, si añades más bombillas iguales, cada una brilla…|En sèrie, si afegixes més bombetes iguals, cadascuna brilla…|In series, adding more identical bulbs makes each one…', 'menos|menys|dimmer', ['más|més|brighter', 'igual|igual|the same'], 'Se reparte el voltaje.|Es repartix el voltatge.|The voltage is shared.'),
      M('Simular un circuito antes de montarlo sirve para…|Simular un circuit abans de muntar-lo servix per a…|Simulating a circuit before building it helps…', 'detectar errores sin riesgo ni gasto|detectar errors sense risc ni despesa|spot mistakes with no risk or cost', ['gastar más componentes|gastar més components|use more components', 'nada|res|nothing'], 'Tinkercad Circuits.|Tinkercad Circuits.|Tinkercad Circuits.'),
      TF('Un cortocircuito ocurre cuando la corriente va directa de un polo al otro sin pasar por un receptor.|Un curtcircuit ocorre quan el corrent va directe d’un pol a l’altre sense passar per un receptor.|A short circuit happens when current flows straight between the terminals without passing through a component.', true, 'Puede calentar y quemar.|Pot escalfar i cremar.|It can overheat and burn.'),
    ]),
  '3E-TD-12': lesson(['Componentes electrónicos analógicos: resistencia (limita la corriente; código de colores), resistencias variables (potenciómetro; LDR, que cambia con la luz; termistor, con la temperatura), diodo (deja pasar la corriente en un solo sentido), LED (diodo que emite luz), condensador (almacena carga) y transistor (amplifica o actúa como interruptor).|Components electrònics analògics: resistència (limita el corrent; codi de colors), resistències variables (potenciòmetre; LDR, que canvia amb la llum; termistor, amb la temperatura), díode (deixa passar el corrent en un sol sentit), LED (díode que emet llum), condensador (emmagatzema càrrega) i transistor (amplifica o actua com a interruptor).|Analogue components: resistor (limits current; colour code), variable resistors (potentiometer; LDR, which changes with light; thermistor, with temperature), diode (lets current through one way only), LED (a diode that gives off light), capacitor (stores charge) and transistor (amplifies or acts as a switch).'],
    '¿Cómo hago una luz que se encienda sola al anochecer?|Com faig una llum que s’encenga sola en fer-se de nit?|How do I make a light that switches on by itself at dusk?', ['Uso una LDR: su resistencia cambia con la luz.|Use una LDR: la seua resistència canvia amb la llum.|Use an LDR: its resistance changes with light.', 'Un transistor activa el LED cuando hay poca luz.|Un transistor activa el LED quan hi ha poca llum.|A transistor turns on the LED when it gets dark.'], [
      M('Un diodo deja pasar la corriente…|Un díode deixa passar el corrent…|A diode lets current through…', 'en un solo sentido|en un sol sentit|in one direction only', ['en los dos sentidos|en els dos sentits|both ways', 'nunca|mai|never'], 'Como una válvula.|Com una vàlvula.|Like a valve.'),
      M('Una LDR es una resistencia que varía con…|Una LDR és una resistència que varia amb…|An LDR is a resistor that changes with…', 'la luz|la llum|light', ['la temperatura|la temperatura|temperature', 'el sonido|el so|sound'], 'Light Dependent Resistor.|Light Dependent Resistor.|Light Dependent Resistor.'),
      M('El componente que puede funcionar como interruptor electrónico o amplificador es…|El component que pot funcionar com a interruptor electrònic o amplificador és…|The component that can act as an electronic switch or amplifier is the…', 'el transistor|el transistor|transistor', ['el LED|el LED|LED', 'la pila|la pila|cell'], 'Base, colector y emisor.|Base, col·lector i emissor.|Base, collector and emitter.'),
      TF('Un LED conectado al revés no se enciende.|Un LED connectat al revés no s’encén.|An LED connected the wrong way round does not light.', true, 'Tiene polaridad: ánodo y cátodo.|Té polaritat: ànode i càtode.|It has polarity: anode and cathode.'),
      M('Un condensador sirve para…|Un condensador servix per a…|A capacitor is used to…', 'almacenar carga eléctrica un tiempo|emmagatzemar càrrega elèctrica un temps|store electric charge for a while', ['emitir luz|emetre llum|give out light', 'medir temperatura|mesurar temperatura|measure temperature'], 'Por ejemplo, en temporizadores.|Per exemple, en temporitzadors.|For example, in timers.'),
      M('Un potenciómetro se usa, por ejemplo, para…|Un potenciòmetre s’usa, per exemple, per a…|A potentiometer is used, for example, to…', 'regular el volumen o el brillo|regular el volum o la brillantor|control volume or brightness', ['convertir corriente alterna|convertir corrent altern|convert AC', 'cargar pilas|carregar piles|charge batteries'], 'Resistencia variable manual.|Resistència variable manual.|A manual variable resistor.'),
    ]),
  '3E-TD-13': lesson(['El sistema operativo gestiona el hardware, los archivos y los programas (Windows, macOS, Linux, Android, iOS). Una red conecta dispositivos para compartir datos: LAN (local), WAN (amplia), Internet (red de redes). Elementos: router, switch, punto de acceso wifi, cables. Cada dispositivo tiene una dirección IP.|El sistema operatiu gestiona el maquinari, els fitxers i els programes (Windows, macOS, Linux, Android, iOS). Una xarxa connecta dispositius per a compartir dades: LAN (local), WAN (àmplia), Internet (xarxa de xarxes). Elements: encaminador (router), commutador (switch), punt d’accés wifi, cables. Cada dispositiu té una adreça IP.|The operating system manages hardware, files and programs (Windows, macOS, Linux, Android, iOS). A network connects devices to share data: LAN (local), WAN (wide area), the internet (a network of networks). Parts: router, switch, Wi-Fi access point, cables. Each device has an IP address.'],
    '¿Qué hace el router de casa?|Què fa el router de casa?|What does a home router do?', ['Conecta la red de casa con Internet.|Connecta la xarxa de casa amb Internet.|It connects the home network to the internet.', 'Y reparte direcciones a los dispositivos.|I repartix adreces als dispositius.|And gives addresses to devices.'], [
      M('La red del aula de informática es una…|La xarxa de l’aula d’informàtica és una…|The computer room network is a…', 'LAN|LAN|LAN', ['WAN|WAN|WAN', 'Internet entera|Internet sencera|the whole internet'], 'Red de área local.|Xarxa d’àrea local.|Local area network.'),
      M('Una dirección IP sirve para…|Una adreça IP servix per a…|An IP address is used to…', 'identificar un dispositivo en la red|identificar un dispositiu en la xarxa|identify a device on a network', ['cifrar contraseñas|xifrar contrasenyes|encrypt passwords', 'cargar la batería|carregar la bateria|charge the battery'], 'Como una dirección postal.|Com una adreça postal.|Like a postal address.'),
      M('¿Cuál es un sistema operativo libre?|Quin és un sistema operatiu lliure?|Which operating system is free and open-source?', 'Linux|Linux|Linux', ['Windows|Windows|Windows', 'iOS|iOS|iOS'], 'Su código se puede ver y modificar.|El seu codi es pot veure i modificar.|Its code can be viewed and changed.'),
      TF('Internet es una red de redes que conecta millones de dispositivos.|Internet és una xarxa de xarxes que connecta milions de dispositius.|The internet is a network of networks linking millions of devices.', true, 'Mundial.|Mundial.|Worldwide.'),
      M('La fibra óptica transmite datos mediante…|La fibra òptica transmet dades mitjançant…|Fibre optics carry data using…', 'pulsos de luz|polsos de llum|pulses of light', ['sonido|so|sound', 'agua|aigua|water'], 'Muy rápida.|Molt ràpida.|Very fast.'),
      M('Una función del sistema operativo es…|Una funció del sistema operatiu és…|One job of the operating system is…', 'gestionar archivos y memoria|gestionar fitxers i memòria|managing files and memory', ['fabricar el procesador|fabricar el processador|making the processor', 'dibujar planos|dibuixar plànols|drawing plans'], 'Intermediario entre usuario y hardware.|Intermediari entre usuari i maquinari.|Go-between for user and hardware.'),
    ]),
  '3E-TD-14': TD1['1E-TD-16'],
  '3E-TD-15': TD1['1E-TD-18'],
  '3E-TD-16': lesson(['Software libre: se puede usar, estudiar, modificar y compartir (LibreOffice, GIMP, Firefox, Linux). Software propietario: su uso está limitado por la licencia del fabricante (Windows, Photoshop). Que no cueste dinero no significa que sea libre. Las licencias Creative Commons regulan el uso de contenidos (textos, imágenes, música).|Programari lliure: es pot usar, estudiar, modificar i compartir (LibreOffice, GIMP, Firefox, Linux). Programari propietari: el seu ús està limitat per la llicència del fabricant (Windows, Photoshop). Sense cost no sempre vol dir lliure. Les llicències Creative Commons regulen l’ús de continguts (textos, imatges, música).|Free software can be used, studied, modified and shared (LibreOffice, GIMP, Firefox, Linux). Proprietary software is restricted by the maker’s licence (Windows, Photoshop). No-cost does not always mean free/open. Creative Commons licences govern use of content (text, images, music).'],
    '¿Es lo mismo software libre que software sin coste?|És el mateix programari lliure que programari sense cost?|Is free (open) software the same as no-cost software?', ['Libre se refiere a la libertad de usar, ver y modificar el código.|Lliure es referix a la llibertat d’usar, veure i modificar el codi.|Free refers to the freedom to use, see and change the code.', 'Un programa sin coste puede ser propietario.|Un programa sense cost pot ser propietari.|A no-cost program can be proprietary.'], [
      M('¿Cuál es software libre?|Quin és programari lliure?|Which is free/open-source software?', 'LibreOffice|LibreOffice|LibreOffice', ['Microsoft Word|Microsoft Word|Microsoft Word', 'Photoshop|Photoshop|Photoshop'], 'Código abierto.|Codi obert.|Open source.'),
      M('El código fuente de un programa libre…|El codi font d’un programa lliure…|The source code of free software…', 'es accesible y se puede modificar|és accessible i es pot modificar|is available and can be changed', ['es secreto|és secret|is secret', 'no existe|no existix|does not exist'], 'Libertad de estudio.|Llibertat d’estudi.|Freedom to study it.'),
      TF('Instalar programas propietarios copiados sin licencia es ilegal.|Instal·lar programes propietaris copiats sense llicència és il·legal.|Installing copied proprietary software without a licence is illegal.', true, 'Piratería.|Pirateria.|Piracy.'),
      M('Una imagen con licencia CC BY-NC se puede usar…|Una imatge amb llicència CC BY-NC es pot usar…|An image with a CC BY-NC licence can be used…', 'citando al autor y sin fines comerciales|citant l’autor i sense finalitats comercials|crediting the author and not for profit', ['para venderla|per a vendre-la|to sell it', 'sin citar|sense citar|without credit'], 'BY: reconocimiento. NC: no comercial.|BY: reconeixement. NC: no comercial.|BY: attribution. NC: non-commercial.'),
      M('GIMP es una alternativa libre a…|GIMP és una alternativa lliure a…|GIMP is a free alternative to…', 'Photoshop|Photoshop|Photoshop', ['Excel|Excel|Excel', 'Chrome|Chrome|Chrome'], 'Edición de imágenes.|Edició d’imatges.|Image editing.'),
      TF('Una ventaja del software libre es que una comunidad puede mejorarlo.|Un avantatge del programari lliure és que una comunitat pot millorar-lo.|One advantage of free software is that a community can improve it.', true, 'Colaboración abierta.|Col·laboració oberta.|Open collaboration.'),
    ]),
  '3E-TD-17': G(['Funciones útiles de la hoja de cálculo: SUMA, PROMEDIO, MAX, MIN, CONTAR, SI (=SI(A1>=5;"Aprobado";"Suspenso")), referencias relativas (A1) y absolutas ($A$1). Con los datos se hacen gráficos: barras, líneas, sectores, dispersión.|Funcions útils del full de càlcul: SUMA, MITJANA, MÀX, MÍN, COMPTA, SI (=SI(A1>=5;"Aprovat";"Suspés")), referències relatives (A1) i absolutes ($A$1). Amb les dades es fan gràfics: barres, línies, sectors, dispersió.|Useful spreadsheet functions: SUM, AVERAGE, MAX, MIN, COUNT, IF (=IF(A1>=5,"Pass","Fail")), relative (A1) and absolute ($A$1) references. Charts can be made from data: bar, line, pie, scatter.'],
    'B2 = 7. ¿Qué da =SI(B2>=5;"Sí";"No")?|B2 = 7. Què dona =SI(B2>=5;"Sí";"No")?|B2 = 7. What does =IF(B2>=5,"Yes","No") give?', ['7 es mayor o igual que 5.|7 és major o igual que 5.|7 is at least 5.', '«Sí».|«Sí».|"Yes".'], spreadsheet(), [
      M('Al copiar una fórmula, la referencia $A$1…|En copiar una fórmula, la referència $A$1…|When you copy a formula, the reference $A$1…', 'no cambia (es absoluta)|no canvia (és absoluta)|does not change (absolute)', ['cambia de fila|canvia de fila|changes row', 'se borra|s’esborra|is deleted'], 'El $ fija fila y columna.|El $ fixa fila i columna.|$ locks row and column.'),
      M('Para ver la evolución de la temperatura durante una semana, el mejor gráfico es…|Per a veure l’evolució de la temperatura durant una setmana, el millor gràfic és…|To show how temperature changes over a week, the best chart is a…', 'de líneas|de línies|line chart', ['de sectores|de sectors|pie chart', 'ninguno|cap|none'], 'Cambios en el tiempo.|Canvis en el temps.|Change over time.'),
    ]),
  '3E-TD-18': TD1['1E-TD-19'],
  '3E-TD-19': lesson(['Un diagrama de flujo representa un algoritmo con símbolos: óvalo (inicio/fin), rectángulo (proceso), rombo (decisión con sí/no), paralelogramo (entrada/salida) y flechas (orden). Ayuda a pensar el programa antes de escribirlo y a encontrar errores.|Un diagrama de flux representa un algorisme amb símbols: oval (inici/fi), rectangle (procés), rombe (decisió amb sí/no), paral·lelogram (entrada/eixida) i fletxes (ordre). Ajuda a pensar el programa abans d’escriure’l i a trobar errors.|A flowchart shows an algorithm using symbols: oval (start/end), rectangle (process), diamond (decision with yes/no), parallelogram (input/output) and arrows (order). It helps you think through a program before writing it and find mistakes.'],
    'En un diagrama, ¿qué símbolo usas para «¿Llueve?»?|En un diagrama, quin símbol uses per a «Plou?»?|In a flowchart, which symbol do you use for "Is it raining?"', ['Es una pregunta con dos salidas.|És una pregunta amb dues eixides.|It is a question with two exits.', 'El rombo (decisión).|El rombe (decisió).|The diamond (decision).'], [
      M('El inicio y el fin se representan con…|L’inici i la fi es representen amb…|Start and end are shown with an…', 'un óvalo|un oval|oval', ['un rombo|un rombe|diamond', 'un círculo pequeño|un cercle xicotet|small circle'], 'Terminal.|Terminal.|Terminator.'),
      M('«Leer un número» se dibuja con…|«Llegir un nombre» es dibuixa amb…|"Read a number" is drawn with a…', 'un paralelogramo|un paral·lelogram|parallelogram', ['un rectángulo|un rectangle|rectangle', 'un óvalo|un oval|oval'], 'Entrada/salida.|Entrada/eixida.|Input/output.'),
      M('«suma = suma + 1» se dibuja con…|«suma = suma + 1» es dibuixa amb…|"total = total + 1" is drawn with a…', 'un rectángulo|un rectangle|rectangle', ['un rombo|un rombe|diamond', 'un paralelogramo|un paral·lelogram|parallelogram'], 'Proceso.|Procés.|Process.'),
      TF('Un bucle se representa con una flecha que vuelve a un paso anterior.|Un bucle es representa amb una fletxa que torna a un pas anterior.|A loop is shown by an arrow going back to an earlier step.', true, 'Repetición.|Repetició.|Repetition.'),
      Nq('Algoritmo: n = 1; mientras n < 20: n = n · 2. ¿Valor final de n?|Algorisme: n = 1; mentre n < 20: n = n · 2. Valor final de n?|Algorithm: n = 1; while n < 20: n = n × 2. Final value of n?', 32, [16, 20, 64], '1, 2, 4, 8, 16, 32.|1, 2, 4, 8, 16, 32.|1, 2, 4, 8, 16, 32.'),
      M('Un diagrama de flujo sirve para…|Un diagrama de flux servix per a…|A flowchart is used to…', 'planificar un algoritmo antes de programarlo|planificar un algorisme abans de programar-lo|plan an algorithm before coding it', ['decorar el código|decorar el codi|decorate code', 'acelerar el ordenador|accelerar l’ordinador|speed up the computer'], 'Pensar antes de escribir.|Pensar abans d’escriure.|Think before you write.'),
    ]),
  '3E-TD-20': G(['Variables, condiciones y bucles combinados permiten resolver problemas complejos: contar, acumular, buscar el mayor, repetir hasta que se cumpla algo. Es importante dar nombres claros a las variables y probar el programa con distintos datos.|Variables, condicions i bucles combinats permeten resoldre problemes complexos: comptar, acumular, buscar el major, repetir fins que es complisca alguna cosa. És important donar noms clars a les variables i provar el programa amb dades diferents.|Combining variables, conditions and loops solves complex problems: counting, accumulating, finding the largest, repeating until something is true. Give variables clear names and test with different data.'],
    'max = 0. Para cada n en [4, 9, 2]: si n > max, max = n. ¿max?|max = 0. Per a cada n en [4, 9, 2]: si n > max, max = n. max?|max = 0. For each n in [4, 9, 2]: if n > max, max = n. max?', ['4 > 0 → 4; 9 > 4 → 9; 2 no.|4 > 0 → 4; 9 > 4 → 9; 2 no.|4 > 0 → 4; 9 > 4 → 9; 2 no.', 'max = 9.|max = 9.|max = 9.'], mix(loops(), (r) => { const xs = Array.from({ length: 4 }, () => 1 + Math.floor(r() * 9)); const lim = 4 + Math.floor(r() * 3); const c = xs.filter((x) => x > lim).length;
      return Nq(`cuenta = 0. Para cada n en [${xs.join(', ')}]: si n > ${lim}, cuenta = cuenta + 1. ¿Cuánto vale cuenta?|compte = 0. Per a cada n en [${xs.join(', ')}]: si n > ${lim}, compte = compte + 1. Quant val compte?|count = 0. For each n in [${xs.join(', ')}]: if n > ${lim}, count = count + 1. What is count?`, c, [0, 1, 2, 3, 4].filter((x) => x !== c).slice(0, 3), `Cuenta los números mayores que ${lim}.|Compta els nombres majors que ${lim}.|Count the numbers greater than ${lim}.`); })),
  '3E-TD-21': lesson(['Las tarjetas controladoras (Arduino, micro:bit, ESP32) son pequeños ordenadores que leen sensores y controlan actuadores según un programa (por bloques o en código). También se pueden crear apps sencillas (App Inventor) que se comunican con ellas por Bluetooth.|Les targetes controladores (Arduino, micro:bit, ESP32) són xicotets ordinadors que lligen sensors i controlen actuadors segons un programa (per blocs o en codi). També es poden crear aplicacions senzilles (App Inventor) que s’hi comuniquen per Bluetooth.|Controller boards (Arduino, micro:bit, ESP32) are small computers that read sensors and control actuators according to a program (blocks or code). Simple apps (App Inventor) can talk to them over Bluetooth.'],
    'Quiero que un ventilador se encienda si hace más de 28 °C. ¿Qué necesito?|Vull que un ventilador s’encenga si fa més de 28 °C. Què necessite?|I want a fan to switch on above 28 °C. What do I need?', ['Sensor de temperatura y motor (actuador).|Sensor de temperatura i motor (actuador).|A temperature sensor and a motor (actuator).', 'Programa: si temperatura > 28, encender motor.|Programa: si temperatura > 28, encendre motor.|Program: if temperature > 28, turn on motor.'], [
      M('En una placa Arduino, un sensor se conecta a una…|En una placa Arduino, un sensor es connecta a una…|On an Arduino, a sensor connects to an…', 'entrada|entrada|input pin', ['salida|eixida|output pin', 'batería|bateria|battery'], 'Lee el valor.|Llig el valor.|It reads the value.'),
      M('La micro:bit tiene integrados…|La micro:bit té integrats…|The micro:bit has built-in…', 'LED, botones, acelerómetro y brújula|LED, botons, acceleròmetre i brúixola|LEDs, buttons, accelerometer and compass', ['una impresora|una impressora|a printer', 'un disco duro|un disc dur|a hard drive'], 'Ideal para empezar.|Ideal per a començar.|Great for beginners.'),
      TF('Una app de móvil puede enviar órdenes a un robot por Bluetooth.|Una aplicació de mòbil pot enviar ordres a un robot per Bluetooth.|A phone app can send commands to a robot by Bluetooth.', true, 'Comunicación inalámbrica.|Comunicació sense fil.|Wireless communication.'),
      M('Un servomotor se usa cuando se necesita…|Un servomotor s’usa quan es necessita…|A servo motor is used when you need…', 'girar a un ángulo concreto|girar a un angle concret|to turn to a precise angle', ['medir la luz|mesurar la llum|to measure light', 'guardar datos|guardar dades|to store data'], 'Por ejemplo, abrir una barrera.|Per exemple, obrir una barrera.|For example, to open a barrier.'),
      M('El bucle principal de Arduino («loop») se ejecuta…|El bucle principal d’Arduino («loop») s’executa…|Arduino’s main loop runs…', 'una y otra vez sin parar|una vegada i una altra sense parar|over and over without stopping', ['una sola vez|una sola vegada|only once', 'nunca|mai|never'], '«setup» solo al principio.|«setup» només al principi.|"setup" runs only at the start.'),
      TF('Para probar un circuito con placa, conviene simularlo antes si es posible.|Per a provar un circuit amb placa, convé simular-lo abans si és possible.|It is wise to simulate a board circuit first if you can.', true, 'Evita romper componentes.|Evita trencar components.|It avoids breaking parts.'),
    ]),
  '3E-TD-22': lesson(['Robótica: máquinas programables que perciben y actúan. Internet de las cosas (IoT): objetos conectados que envían datos (termostatos, relojes, sensores de riego). Con la inteligencia artificial, estos sistemas pueden aprender y tomar decisiones. Beneficios: eficiencia, accesibilidad. Riesgos: privacidad, seguridad, dependencia.|Robòtica: màquines programables que perceben i actuen. Internet de les coses (IoT): objectes connectats que envien dades (termòstats, rellotges, sensors de reg). Amb la intel·ligència artificial, estos sistemes poden aprendre i prendre decisions. Beneficis: eficiència, accessibilitat. Riscos: privacitat, seguretat, dependència.|Robotics: programmable machines that sense and act. The Internet of Things (IoT): connected objects that send data (thermostats, watches, irrigation sensors). With AI, these systems can learn and make decisions. Benefits: efficiency, accessibility. Risks: privacy, security, dependence.'],
    'Un sensor de humedad en un huerto envía datos al móvil. ¿Qué es?|Un sensor d’humitat en un hort envia dades al mòbil. Què és?|A soil moisture sensor in a garden sends data to a phone. What is it?', ['Es un objeto conectado a Internet.|És un objecte connectat a Internet.|It is an internet-connected object.', 'Internet de las cosas (IoT).|Internet de les coses (IoT).|Internet of Things (IoT).'], [
      M('Un riesgo del IoT es…|Un risc de l’IoT és…|A risk of IoT is…', 'que roben o espíen datos si no es seguro|que roben o espien dades si no és segur|data theft or spying if it is not secure', ['que gaste poca batería|que gaste poca bateria|low battery use', 'que sea útil|que siga útil|being useful'], 'Cambiar contraseñas por defecto.|Canviar contrasenyes per defecte.|Change default passwords.'),
      TF('Los robots industriales hacen tareas repetitivas o peligrosas.|Els robots industrials fan tasques repetitives o perilloses.|Industrial robots do repetitive or dangerous jobs.', true, 'Soldar, pintar, mover cargas.|Soldar, pintar, moure càrregues.|Welding, painting, moving loads.'),
      M('Un ejemplo de robot en medicina es…|Un exemple de robot en medicina és…|An example of a robot in medicine is…', 'el robot que ayuda en cirugías|el robot que ajuda en cirurgies|a robot that assists in surgery', ['un termómetro de mercurio|un termòmetre de mercuri|a mercury thermometer', 'una venda|una bena|a bandage'], 'Gran precisión.|Gran precisió.|High precision.'),
      M('Un termostato inteligente ahorra energía porque…|Un termòstat intel·ligent estalvia energia perquè…|A smart thermostat saves energy because…', 'aprende horarios y ajusta la temperatura|aprén horaris i ajusta la temperatura|it learns routines and adjusts the temperature', ['funciona siempre al máximo|funciona sempre al màxim|it always runs at full power', 'no tiene sensores|no té sensors|it has no sensors'], 'IoT + IA.|IoT + IA.|IoT + AI.'),
      TF('Todo dispositivo conectado debe tener una contraseña segura, no la de fábrica.|Tot dispositiu connectat ha de tindre una contrasenya segura, no la de fàbrica.|Every connected device should have a secure password, not the factory one.', true, 'Muchos ataques usan contraseñas por defecto.|Molts atacs usen contrasenyes per defecte.|Many attacks use default passwords.'),
      M('Un coche autónomo usa sensores e IA para…|Un cotxe autònom usa sensors i IA per a…|A self-driving car uses sensors and AI to…', 'percibir el entorno y decidir cómo conducir|percebre l’entorn i decidir com conduir|sense its surroundings and decide how to drive', ['cambiar de color|canviar de color|change colour', 'gastar más gasolina|gastar més gasolina|use more fuel'], 'Cámaras, radar, lidar.|Càmeres, radar, lidar.|Cameras, radar, lidar.'),
    ]),
  '3E-TD-23': lesson(['La inteligencia artificial (IA) son sistemas que realizan tareas que parecen requerir inteligencia: reconocer imágenes y voz, traducir, recomendar, generar textos. El aprendizaje automático aprende patrones a partir de muchos datos de entrenamiento. Puede equivocarse, tener sesgos y no «entiende» como una persona: hay que usarla con criterio.|La intel·ligència artificial (IA) són sistemes que realitzen tasques que semblen requerir intel·ligència: reconéixer imatges i veu, traduir, recomanar, generar textos. L’aprenentatge automàtic aprén patrons a partir de moltes dades d’entrenament. Es pot equivocar, tindre biaixos i no «entén» com una persona: cal usar-la amb criteri.|Artificial intelligence (AI) is systems doing tasks that seem to need intelligence: recognising images and speech, translating, recommending, generating text. Machine learning finds patterns in large amounts of training data. It can be wrong, can be biased and does not "understand" like a person: use it with judgement.'],
    'Una IA que reconoce gatos, ¿cómo ha aprendido?|Una IA que reconeix gats, com ha aprés?|How did an AI that recognises cats learn?', ['Con miles de fotos etiquetadas «gato» y «no gato».|Amb milers de fotos etiquetades «gat» i «no gat».|From thousands of photos labelled "cat" and "not cat".', 'Encuentra patrones en los datos.|Troba patrons en les dades.|It finds patterns in the data.'], [
      M('Los datos con los que aprende una IA se llaman…|Les dades amb què aprén una IA s’anomenen…|The data an AI learns from is called…', 'datos de entrenamiento|dades d’entrenament|training data', ['contraseñas|contrasenyes|passwords', 'virus|virus|viruses'], 'Cuanto mejores, mejor aprende.|Com millors, millor aprén.|Better data, better learning.'),
      TF('Una IA puede dar respuestas falsas con mucha seguridad.|Una IA pot donar respostes falses amb molta seguretat.|An AI can give false answers very confidently.', true, 'Hay que comprobar lo que dice.|Cal comprovar el que diu.|Check what it says.'),
      M('Un sesgo en IA ocurre cuando…|Un biaix en IA ocorre quan…|Bias in AI happens when…', 'los datos de entrenamiento no representan bien a todos|les dades d’entrenament no representen bé tots|the training data does not represent everyone fairly', ['el ordenador está apagado|l’ordinador està apagat|the computer is off', 'la pantalla es pequeña|la pantalla és xicoteta|the screen is small'], 'Puede discriminar.|Pot discriminar.|It can discriminate.'),
      M('¿Cuál es un uso correcto de la IA para estudiar?|Quin és un ús correcte de la IA per a estudiar?|Which is a good way to use AI for study?', 'pedirle que te explique un concepto y comprobarlo|demanar-li que t’explique un concepte i comprovar-ho|asking it to explain an idea and checking it', ['copiar su respuesta sin leer|copiar la seua resposta sense llegir|copying its answer without reading it', 'entregar su texto como propio|lliurar el seu text com a propi|handing in its text as yours'], 'Úsala como apoyo, no como atajo.|Usa-la com a suport, no com a drecera.|Use it as support, not a shortcut.'),
      TF('Una IA entiende y siente igual que una persona.|Una IA entén i sent igual que una persona.|An AI understands and feels just like a person.', false, 'Procesa patrones; no tiene experiencias.|Processa patrons; no té experiències.|It processes patterns; it has no experiences.'),
      M('Las recomendaciones de vídeos de una plataforma se basan en…|Les recomanacions de vídeos d’una plataforma es basen en…|A platform’s video recommendations are based on…', 'lo que has visto y lo que ven usuarios parecidos|el que has vist i el que veuen usuaris semblants|what you watched and what similar users watch', ['el azar puro|l’atzar pur|pure chance', 'el color de tu móvil|el color del teu mòbil|your phone colour'], 'Pueden encerrarte en una burbuja.|Et poden tancar en una bombolla.|They can trap you in a bubble.'),
    ]),
  '3E-TD-24': lesson(['La tecnología tiene impacto ambiental en todo su ciclo de vida: extracción de materias primas (minería de metales para móviles), fabricación, transporte, uso (consumo energético) y residuos (basura electrónica). Soluciones: diseño ecológico, alargar la vida útil, reparar, reutilizar y reciclar.|La tecnologia té impacte ambiental en tot el seu cicle de vida: extracció de matèries primeres (mineria de metalls per a mòbils), fabricació, transport, ús (consum energètic) i residus (fem electrònic). Solucions: disseny ecològic, allargar la vida útil, reparar, reutilitzar i reciclar.|Technology affects the environment across its whole life cycle: raw materials (mining metals for phones), manufacturing, transport, use (energy) and waste (e-waste). Solutions: eco-design, longer life, repair, reuse and recycling.'],
    '¿Qué hacer con un móvil viejo que funciona?|Què fer amb un mòbil vell que funciona?|What should you do with an old phone that still works?', ['Reutilizarlo o donarlo.|Reutilitzar-lo o donar-lo.|Reuse it or give it away.', 'Si no sirve, llevarlo a un punto limpio para reciclar.|Si no servix, portar-lo a un ecoparc per a reciclar.|If it is no use, take it to a recycling centre.'], [
      M('La obsolescencia programada es…|L’obsolescència programada és…|Planned obsolescence is…', 'diseñar productos para que duren poco|dissenyar productes perquè duren poc|designing products not to last', ['reciclar más|reciclar més|recycling more', 'una ley ambiental|una llei ambiental|an environmental law'], 'Obliga a comprar de nuevo.|Obliga a comprar de nou.|It forces you to buy again.'),
      TF('Fabricar un móvil consume más energía y recursos que usarlo un año.|Fabricar un mòbil consumix més energia i recursos que usar-lo un any.|Making a phone uses more energy and resources than using it for a year.', true, 'Por eso conviene alargar su vida.|Per això convé allargar-ne la vida.|So make it last longer.'),
      M('El análisis de ciclo de vida estudia…|L’anàlisi de cicle de vida estudia…|Life-cycle analysis studies…', 'el impacto de un producto desde que se fabrica hasta que se desecha|l’impacte d’un producte des que es fabrica fins que es rebutja|a product’s impact from manufacture to disposal', ['solo el precio|només el preu|only the price', 'solo el diseño|només el disseny|only the design'], 'De la cuna a la tumba.|Del bressol a la tomba.|Cradle to grave.'),
      M('Los residuos electrónicos contienen…|Els residus electrònics contenen…|E-waste contains…', 'metales valiosos y sustancias tóxicas|metalls valuosos i substàncies tòxiques|valuable metals and toxic substances', ['solo plástico|només plàstic|only plastic', 'nada útil|res útil|nothing useful'], 'Oro, cobre, plomo, mercurio.|Or, coure, plom, mercuri.|Gold, copper, lead, mercury.'),
      TF('Los centros de datos de Internet consumen mucha electricidad.|Els centres de dades d’Internet consumixen molta electricitat.|Internet data centres use a lot of electricity.', true, 'Y agua para refrigerarse.|I aigua per a refrigerar-se.|And water for cooling.'),
      M('El ecodiseño busca…|L’ecodisseny busca…|Eco-design aims for…', 'productos duraderos, reparables y reciclables|productes duradors, reparables i reciclables|durable, repairable, recyclable products', ['productos de un solo uso|productes d’un sol ús|single-use products', 'más embalaje|més embalatge|more packaging'], 'Menos impacto.|Menys impacte.|Lower impact.'),
    ]),
  '3E-TD-25': lesson(['La energía eléctrica se produce en centrales: no renovables (térmicas de carbón y gas, nucleares) y renovables (hidráulica, eólica, solar fotovoltaica y térmica, biomasa). Cada una tiene impactos: emisiones de CO₂, residuos radiactivos, ocupación del territorio, paisaje. El futuro pasa por renovables, eficiencia y almacenamiento (baterías).|L’energia elèctrica es produïx en centrals: no renovables (tèrmiques de carbó i gas, nuclears) i renovables (hidràulica, eòlica, solar fotovoltaica i tèrmica, biomassa). Cadascuna té impactes: emissions de CO₂, residus radioactius, ocupació del territori, paisatge. El futur passa per renovables, eficiència i emmagatzematge (bateries).|Electricity is produced in power stations: non-renewable (coal and gas, nuclear) and renewable (hydro, wind, solar PV and solar thermal, biomass). Each has impacts: CO₂ emissions, radioactive waste, land use, landscape. The future lies in renewables, efficiency and storage (batteries).'],
    '¿Qué problema tienen la solar y la eólica?|Quin problema tenen la solar i l’eòlica?|What problem do solar and wind have?', ['No producen siempre: depende del sol y del viento.|No produïxen sempre: depén del sol i del vent.|They do not always produce: it depends on sun and wind.', 'Hace falta almacenar energía (baterías, bombeo).|Cal emmagatzemar energia (bateries, bombament).|Energy storage is needed (batteries, pumped hydro).'], [
      M('¿Qué central emite más CO₂?|Quina central emet més CO₂?|Which power station emits the most CO₂?', 'térmica de carbón|tèrmica de carbó|coal-fired', ['eólica|eòlica|wind', 'hidráulica|hidràulica|hydroelectric'], 'Quema combustible fósil.|Crema combustible fòssil.|It burns fossil fuel.'),
      M('La central nuclear obtiene energía de…|La central nuclear obté energia de…|A nuclear power station gets energy from…', 'la fisión de núcleos de uranio|la fissió de nuclis d’urani|splitting uranium nuclei', ['quemar carbón|cremar carbó|burning coal', 'el viento|el vent|the wind'], 'No emite CO₂ al funcionar, pero genera residuos radiactivos.|No emet CO₂ en funcionar, però genera residus radioactius.|No CO₂ in operation, but radioactive waste.'),
      TF('La biomasa es una energía renovable.|La biomassa és una energia renovable.|Biomass is a renewable energy source.', true, 'Si se repone lo que se quema.|Si es reposa el que es crema.|If what is burnt is replaced.'),
      M('Una placa solar fotovoltaica convierte…|Una placa solar fotovoltaica convertix…|A solar PV panel converts…', 'luz en electricidad|llum en electricitat|light into electricity', ['calor en agua|calor en aigua|heat into water', 'viento en luz|vent en llum|wind into light'], 'Efecto fotovoltaico.|Efecte fotovoltaic.|Photovoltaic effect.'),
      M('El autoconsumo solar consiste en…|L’autoconsum solar consistix en…|Solar self-consumption means…', 'producir tu propia electricidad con placas en tu casa|produir la teua pròpia electricitat amb plaques a casa|making your own electricity with panels at home', ['comprar más electricidad|comprar més electricitat|buying more electricity', 'apagar la luz|apagar la llum|switching off lights'], 'Cada vez más común.|Cada vegada més comú.|Increasingly common.'),
      M('Un impacto de los grandes parques eólicos es…|Un impacte dels grans parcs eòlics és…|One impact of large wind farms is…', 'el paisaje y el riesgo para algunas aves|el paisatge i el risc per a alguns ocells|on landscapes and some birds', ['la emisión de CO₂ al funcionar|l’emissió de CO₂ en funcionar|CO₂ emissions in use', 'residuos radiactivos|residus radioactius|radioactive waste'], 'Ninguna energía tiene impacto cero.|Cap energia té impacte zero.|No energy source has zero impact.'),
    ]),
};
export default P;
